#include <stdio.h>
typedef int StackElementType;

/* ============================================================
   两栈共享一片数组空间：3.5 InitStack / 3.6 Push / 3.7 Pop
   摘自教材配套源码（耿国华《数据结构——用C语言描述》第 3 章），原样保留。
   下列 main 为课堂演示驱动，可自由修改后重新运行。
   ============================================================ */
#define TRUE 1
#define FALSE 0
#define M 100

typedef struct
{
	StackElementType Stack[M];
	StackElementType top[2];  /*top[0]和top[1]分别为两个栈顶指示器*/
}DqStack;

/*初始化操作。*/
void InitStack(DqStack *S)
{
	S->top[0]=-1;
	S->top[1]=M;
}

/*进栈操作。*/
int Push(DqStack *S,StackElementType x,int i)
{
	/*把数据元素x压入i号堆栈*/
	if(S->top[0]+1==S->top[1]) /*栈已满*/
		return(FALSE);
	switch(i)
	{
	case 0:
		S->top[0]++;
		S->Stack[S->top[0]]=x;
		break;
	case 1:
		S->top[1]--;
		S->Stack[S->top[1]]=x;
		break;
	default:  /*参数错误*/
        return(FALSE);  /* 原书此处漏了分号，为能编译已补 */
 	}
	return(TRUE);
}

/*出栈操作。*/
int Pop(DqStack *S,StackElementType *x,int i)
{
	/* 从i 号堆栈中弹出栈顶元素并送到x中 */
	switch(i)
	{
	case 0:
		if(S->top[0]==-1)  
			return(FALSE);
		*x=S->Stack[S->top[0]];
		S->top[0]--;
		break;
	case 1:
		if(S->top[1]==M)  
			return(FALSE);
		*x=S->Stack[S->top[1]];
		S->top[1]++;
		break;
	default:
		return(FALSE);
	}
	return(TRUE);
}


int main(void) {
  DqStack S;
  StackElementType x;
  int i;

  InitStack(&S);
  for (i = 1; i <= 3; i++) Push(&S, i * 100, 0);
  for (i = 1; i <= 2; i++) Push(&S, i * 7, 1);

  printf("0 号栈 top[0] = %d，1 号栈 top[1] = %d\n", S.top[0], S.top[1]);
  printf("两栈之间还剩 %d 个空位\n", S.top[1] - S.top[0] - 1);

  printf("0 号栈出栈: ");
  while (Pop(&S, &x, 0) == TRUE) printf("%d ", x);
  printf("\n1 号栈出栈: ");
  while (Pop(&S, &x, 1) == TRUE) printf("%d ", x);
  putchar('\n');
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef char StackElementType;

/* ============================================================
   链栈的进栈与出栈：3.8 Push / 3.9 Pop
   摘自教材配套源码（耿国华《数据结构——用C语言描述》第 3 章），原样保留。
   下列 main 为课堂演示驱动，可自由修改后重新运行。
   ============================================================ */
#define TRUE 1
#define FALSE 0

typedef struct node
{
	StackElementType data;
	struct node *next;
}LinkStackNode;

typedef LinkStackNode *LinkStack;

/*进栈操作。*/
int Push(LinkStack top, StackElementType x)/* 将数据元素x压入栈top中 */ 
{
	LinkStackNode *temp;
	temp=(LinkStackNode *)malloc(sizeof(LinkStackNode));
 	if(temp==NULL)  
 		return(FALSE);   /* 申请空间失败 */
	temp->data=x;
	temp->next=top->next;
	top->next=temp;   /* 修改当前栈顶指针 */ 
	return(TRUE);
}

/*出栈操作。*/
int Pop(LinkStack top, StackElementType *x)
{  
	/* 将栈top的栈顶元素弹出，放到x所指的存储空间中 */
	LinkStackNode * temp;
	temp=top->next;
	if(temp==NULL)  /*栈为空*/
		return(FALSE);
	top->next=temp->next;
	*x=temp->data;
	free(temp);   /* 释放存储空间 */
	return(TRUE);
}



int main(void) {
  LinkStackNode head;
  char c, top;
  int count = 0;

  head.next = NULL;
  while ((c = (char)getchar()) != '\n' && c != EOF) {
    if (c == ' ') continue;
    Push(&head, c);
    count++;
  }

  printf("链栈元素个数: %d\n", count);
  printf("依次出栈: ");
  while (Pop(&head, &top) == TRUE) putchar(top);
  putchar('\n');
  printf("Pop 空栈返回: %d\n", Pop(&head, &top));
  return 0;
}
